55	const PROCESSING_FEE = 5;
56	
57	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
58	
59	const BASE_PREMIUMS = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	  potion: 40,
64	  rune: 25,
65	  moonstone: 25,
66	} as const satisfies Record<string, number>;
67	
68	type PricedItemType = keyof typeof BASE_PREMIUMS;
69	
70	const hasBasePremium = (type: string): type is PricedItemType =>
71	  type in BASE_PREMIUMS;
72	
73	// Unknown item types are not yet rejected — the spec requires an error, but no
74	// test drives that behaviour yet, so they are priced at 0 for the moment.
75	const UNPRICED_UNKNOWN_TYPE = 0;
76	
77	const basePremiumForItem = (item: Item): number =>
78	  hasBasePremium(item.type)
79	    ? BASE_PREMIUMS[item.type]
80	    : UNPRICED_UNKNOWN_TYPE;
81	
82	const BLOCK_SIZE = 3;
83	
84	const BLOCK_BASE_PREMIUM = 60;
85	
86	// "Alike" means the same exact type, not merely the same family: two runes and
87	// a moonstone are three components but not three alike ones, so they carry no
88	// block price.
89	const areAlike = (items: Item[]): boolean =>
90	  items.every((item) => item.type === items[0]?.type);
91	
92	// A block is not carved out of a larger group: the block price applies only
93	// when the group consists of exactly three alike components (7 runes cost
94	// 7 × 25, not 60 + 60 + 25).
95	const qualifiesForBlockPrice = (items: Item[]): boolean =>
96	  items.length === BLOCK_SIZE && areAlike(items);
97	
98	const sumBasePremiums = (items: Item[]): number =>
99	  items.reduce((sum, item) => sum + basePremiumForItem(item), 0);
100	
101	const groupByType = (items: Item[]): Item[][] => {
102	  const groups = new Map<string, Item[]>();
103	  for (const item of items) {
104	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
105	  }
106	  return [...groups.values()];
107	};
108	
109	const basePremiumForGroup = (group: Item[]): number =>
110	  qualifiesForBlockPrice(group) ? BLOCK_BASE_PREMIUM : sumBasePremiums(group);
111	
112	const basePremiumForItems = (items: Item[]): number =>
113	  groupByType(items).reduce(
114	    (sum, group) => sum + basePremiumForGroup(group),
115	    0,
116	  );
117	
118	const withInitialAssessmentSurcharge = (basePremium: number): number =>
119	  basePremium * (1 + INITIAL_ASSESSMENT_SURCHARGE);
120	
121	const quotePremium = (items: Item[]): number =>
122	  Math.round(
123	    withInitialAssessmentSurcharge(basePremiumForItems(items)) + PROCESSING_FEE,
124	  );
125	
126	const runStep = (step: Step): StepResult => {
127	  if (step.op === "quote") return { premium: quotePremium(step.items) };
128	  throw new Error(`Unsupported step: ${step.op}`);
129	};
130	
131	export const runScenario = (scenario: Scenario): ScenarioResult => ({
132	  results: scenario.steps.map(runStep),
133	});
